description:
With several objects selected, each field shows one value or "mixed". Write

```cpp
struct Object { int id; std::map<std::string, double> fields; };

std::string shownValue(const std::vector<Object>& selected, const std::string& field);
void setAll(std::vector<Object>& selected, const std::string& field, double value);
void addAll(std::vector<Object>& selected, const std::string& field, double delta);
```

- `shownValue`: `"--"` if the values differ between the selected objects; otherwise the common value written with `std::to_string` and trailing zeros after the decimal point removed (and the point too if nothing is left after it): `5`, `2.5`, `-0.125`. An object without the field does not count; if no selected object has it (or nothing is selected), return `""`.
- `setAll` writes the value into every selected object **that has** the field.
- `addAll` adds `delta` to the field of every selected object that has it (a relative drag: their differences stay the same).

starter.solution.cpp:
#include <map>
#include <string>
#include <vector>

struct Object { int id; std::map<std::string, double> fields; };

std::string shownValue(const std::vector<Object>& selected, const std::string& field) { return ""; }
void setAll(std::vector<Object>& selected, const std::string& field, double value) {}
void addAll(std::vector<Object>& selected, const std::string& field, double delta) {}

solution.solution.cpp:
#include <map>
#include <string>
#include <vector>

struct Object { int id; std::map<std::string, double> fields; };

static std::string tidy(double v)
{
    std::string s{ std::to_string(v) };
    if (s.find('.') != std::string::npos)
    {
        while (!s.empty() && s.back() == '0') s.pop_back();
        if (!s.empty() && s.back() == '.') s.pop_back();
    }
    if (s == "-0") s = "0";
    return s;
}

std::string shownValue(const std::vector<Object>& selected, const std::string& field)
{
    bool any{ false };
    double first{ 0.0 };
    for (const Object& o : selected)
    {
        const auto it{ o.fields.find(field) };
        if (it == o.fields.end()) continue;
        if (!any) { first = it->second; any = true; }
        else if (it->second != first) return "--";
    }
    return any ? tidy(first) : "";
}

void setAll(std::vector<Object>& selected, const std::string& field, double value)
{
    for (Object& o : selected) { auto it{ o.fields.find(field) }; if (it != o.fields.end()) it->second = value; }
}

void addAll(std::vector<Object>& selected, const std::string& field, double delta)
{
    for (Object& o : selected) { auto it{ o.fields.find(field) }; if (it != o.fields.end()) it->second += delta; }
}

unitTests:
std::vector<Object> lights() { return { { 1, { { "intensity", 5 }, { "range", 10 } } }, { 2, { { "intensity", 5 }, { "range", 12.5 } } }, { 3, { { "intensity", 5 } } } }; }
TEST("same value") { CHECK_EQ(shownValue(lights(), "intensity"), std::string("5")); }
TEST("mixed") { CHECK_EQ(shownValue(lights(), "range"), std::string("--")); }
TEST("missing field") { CHECK_EQ(shownValue(lights(), "colour"), std::string("")); CHECK_EQ(shownValue({}, "intensity"), std::string("")); }
TEST("formatting") { std::vector<Object> a{ { 1, { { "x", 2.5 } } } }; CHECK_EQ(shownValue(a, "x"), std::string("2.5")); a[0].fields["x"] = -0.125; CHECK_EQ(shownValue(a, "x"), std::string("-0.125")); }
TEST("set all") { auto s = lights(); setAll(s, "range", 20); CHECK_EQ(shownValue(s, "range"), std::string("20")); CHECK(!s[2].fields.count("range")); }
TEST("relative") { auto s = lights(); addAll(s, "range", 2); CHECK_NEAR(s[0].fields["range"], 12.0, 1e-9); CHECK_NEAR(s[1].fields["range"], 14.5, 1e-9); CHECK_EQ(shownValue(s, "range"), std::string("--")); }

